const items = $input.all();
const urls = [];

for (const item of items) {
  const urlset = item.json.urlset;
  if (urlset && urlset.url) {
    const entries = Array.isArray(urlset.url) ? urlset.url : [urlset.url];
    for (const entry of entries) {
      if (entry.loc) urls.push(entry.loc);
    }
  }
}

return [{ json: { links: urls } }];

const results = [];

for (const item of $input.all()) {
  const html = item.json.data || item.json.body || '';
  const url = (item.json.headers && item.json.headers['x-request-url']) || item.json.url || '';

  let title = '';
  let description = '';
  let text = '';

  try {
    const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
    title = titleMatch ? titleMatch[1].trim() : '';

    const descMatch = html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i);
    description = descMatch ? descMatch[1].trim() : '';

    let body = html;
    body = body.replace(/<script[\s\S]*?<\/script>/gi, ' ');
    body = body.replace(/<style[\s\S]*?<\/style>/gi, ' ');
    body = body.replace(/<nav[\s\S]*?<\/nav>/gi, ' ');
    body = body.replace(/<footer[\s\S]*?<\/footer>/gi, ' ');
    body = body.replace(/<!--[\s\S]*?-->/g, ' ');
    body = body.replace(/<[^>]+>/g, ' ');
    body = body.replace(/&nbsp;/g, ' ');
    body = body.replace(/&amp;/g, '&');
    body = body.replace(/&quot;/g, '"');
    body = body.replace(/&#39;/g, "'");
    text = body.replace(/\s+/g, ' ').trim();
  } catch (e) {
    text = '';
  }

  results.push({
    json: {
      metadata: { title, description, url },
      markdown: text
    }
  });
}

return results;

const item = $input.first().json;
const sitemapIndex = item.sitemapindex;
let locs = [];

if (sitemapIndex && sitemapIndex.sitemap) {
  const entries = Array.isArray(sitemapIndex.sitemap) ? sitemapIndex.sitemap : [sitemapIndex.sitemap];
  // Only follow the sitemap that covers actual site pages, skip posts/categories/authors/qr
  const pageSitemap = entries.find(e => e.loc.includes('page-sitemap'));
  if (pageSitemap) {
    locs = [{ json: { nestedSitemapUrl: pageSitemap.loc } }];
  } else {
    // fallback: if no page-sitemap found, just take the first one
    locs = [{ json: { nestedSitemapUrl: entries[0].loc } }];
  }
}

return locs;
